export const dimensions={structure:['Sin iniciar','Sin estructura','En ejecución','Estructurado','Revisado'],closure:['Pendiente','Parcial','Continuo cerrado','Paneles instalados'],finish:['Pendiente','En ejecución','Terminado'],mep:['Sin verificar','Pendiente','En ejecución','Verificado'],inspection:['Pendiente','Observado','Inspeccionado','Aprobado'],floor:['Pendiente','Preparación de base','Instalación iniciada','Instalación parcial','Instalación completada','Remates pendientes','Inspeccionado','Aprobado']};
export const dimensionNames={structure:'Estructura',closure:'Cierre / paneles',finish:'Terminaciones',mep:'MEP',inspection:'Inspección',floor:'Pavimento'};
export const technicalStates=['Pendiente','Emitido','En revisión','Observado','Aprobado'];
export function uid(){const b=crypto.getRandomValues(new Uint8Array(16));b[6]=(b[6]&15)|64;b[8]=(b[8]&63)|128;return [...b].map(v=>v.toString(16).padStart(2,'0')).join('');}
export function validatePolygon(p){if(!Array.isArray(p)||p.length<3||!p.every(q=>Array.isArray(q)&&q.length===2&&q.every(Number.isFinite)))throw Error('Contorno inválido');let area=0;const n=p.length,cross=(a,b,c)=>(b[0]-a[0])*(c[1]-a[1])-(b[1]-a[1])*(c[0]-a[0]);for(let i=0;i<n;i++){const a=p[i],b=p[(i+1)%n];if(Math.hypot(a[0]-b[0],a[1]-b[1])<.01)throw Error('Vértices repetidos');area+=a[0]*b[1]-b[0]*a[1];for(let j=i+2;j<n;j++){if(i===0&&j===n-1)continue;const c=p[j],d=p[(j+1)%n];if(cross(a,b,c)*cross(a,b,d)<=0&&cross(c,d,a)*cross(c,d,b)<=0&&Math.max(Math.min(a[0],b[0]),Math.min(c[0],d[0]))<=Math.min(Math.max(a[0],b[0]),Math.max(c[0],d[0]))&&Math.max(Math.min(a[1],b[1]),Math.min(c[1],d[1]))<=Math.min(Math.max(a[1],b[1]),Math.max(c[1],d[1])))throw Error('Contorno cruzado: corrige los vértices');}}if(Math.abs(area)<.1)throw Error('Contorno sin superficie');return Math.abs(area)/2;}
export function validateEvent(e){if(!e.zoneId||!dimensions[e.dimension]?.includes(e.state)||!/^\d{4}-\d{2}-\d{2}$/.test(e.date)||new Date(e.date).toISOString().slice(0,10)!==e.date)throw Error('Zona, estado o fecha no válidos');return e;}
export function validateProtocol(p){if(!p.id||!p.number?.trim()||!p.specialty?.trim()||!technicalStates.includes(p.technical)||!['Abierto','Cerrado'].includes(p.administrative)||!Array.isArray(p.elements)||!p.elements.length)throw Error('Protocolo incompleto');return p;}
export function protocolCounts(rows,planned=null){const unique=[...new Map(rows.map(p=>[p.id,p])).values()];return {registered:unique.length,approved:unique.filter(p=>p.technical==='Aprobado').length,observed:unique.filter(p=>p.technical==='Observado').length,compliance:Number.isInteger(planned)&&planned>0&&unique.length<=planned?unique.filter(p=>p.technical==='Aprobado').length/planned:null};}
const tables=['zones','events','protocols','reviews','history'],open=()=>new Promise((resolve,reject)=>{const r=indexedDB.open('atlas-construction',2);r.onupgradeneeded=()=>{for(const k of [...tables,'backups'])if(!r.result.objectStoreNames.contains(k))r.result.createObjectStore(k,{keyPath:'id'});};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});
export async function records(table){const db=await open();try{return await new Promise((resolve,reject)=>{const q=db.transaction(table).objectStore(table).getAll();q.onsuccess=()=>resolve(q.result.sort((a,b)=>(a.at||'').localeCompare(b.at||'')));q.onerror=()=>reject(q.error);});}finally{db.close();}}
export async function persist(table,item){if(table==='zones')validatePolygon(item.points);if(table==='events')validateEvent(item);if(table==='protocols')validateProtocol(item);const db=await open();try{await new Promise((resolve,reject)=>{const tx=db.transaction([table,'history'],'readwrite');tx.objectStore(table).put(item);tx.objectStore('history').add({id:uid(),at:new Date().toISOString(),table,item});tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||Error('No se pudo guardar'));});}finally{db.close();}if(typeof window!=='undefined')window.dispatchEvent(new Event('atlas-work-changed'));return item;}
export async function backupWork(){const result={format:'atlas-construction-v1',at:new Date().toISOString()};for(const k of tables)result[k]=await records(k);return result;}
export async function restoreWork(value){if(value?.format!=='atlas-construction-v1'||!tables.every(k=>Array.isArray(value[k])))throw Error('Respaldo no reconocido');value.events.forEach(validateEvent);value.protocols.forEach(validateProtocol);value.zones.forEach(z=>{if(!z.id||!z.roomCode||!z.sheetId)throw Error('Zona sin identidad');validatePolygon(z.points);});const ids=new Set(value.zones.map(z=>z.id));if(value.events.some(e=>!ids.has(e.zoneId)))throw Error('Evento sin zona');for(const k of tables)if(value[k].some(v=>typeof v.id!=='string'||!v.id))throw Error('Registro sin identificador');const previous=await backupWork(),db=await open();let skipped=0;try{await new Promise((resolve,reject)=>{const tx=db.transaction([...tables,'backups'],'readwrite');tx.objectStore('backups').add({...previous,id:uid()});for(const k of tables)for(const item of value[k]){const req=tx.objectStore(k).get(item.id);req.onsuccess=()=>{if(req.result){skipped++;}else tx.objectStore(k).add(item);};}tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||Error('Restauración cancelada'));});}finally{db.close();}return skipped;}
